const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const R=path.resolve(__dirname,'..'),main=path.resolve(process.env.ATOMIC_RULES_REPO||path.resolve(R,'../../..')),read=n=>fs.readFileSync(path.join(R,n),'utf8');
const A='总打码倍数1.3720(有效投注137.2/总充值100)小于配置4',B='累计提款次数0小于配置1次',C='首存金额5000大于等于配置4999';
const q={country:'印度',platform:'WG-SYNTHETIC',date:'2026-09-30',kind:'blocking',limit:500};
const unaffected=[{kind:'categories'},{kind:'rejection'},{kind:'operators'},{kind:'orders'},{kind:'orders',query:'VERIFIED'},{kind:'orders',offset:20}];
async function wg(clear=false){let run;const source=fs.readFileSync(path.join(main,'tests/wg-withdraw-blocking-canonical-groups.test.cjs'),'utf8');const req=x=>x==='node:test'?{test:()=>{},before:f=>run=f,after:()=>{}}:require(x);const api=new Function('require','__dirname',source+';return {get:()=>db,call,seed,manual,checksum};')(req,path.join(main,'tests'));await run();const db=api.get();await db.exec('alter table public.wg_withdraw_details add primary key(site_code,order_number)');if(clear)await db.exec('delete from public.wg_withdraw_details;delete from private.wg_verified_front_rejection_notes;');await db.exec(read('baseline/dashboard_admin_wg_withdraw_reasons.sql'));await db.exec('revoke all on function private.dashboard_admin_wg_withdraw_reasons(jsonb,jsonb)from public,anon,authenticated,service_role');
 const originalMeta=(await db.query("select to_jsonb(p)v from pg_proc p where oid='private.dashboard_admin_wg_withdraw_reasons(jsonb,jsonb)'::regprocedure")).rows[0].v;
 const beforeRejections=[];for(const e of unaffected)beforeRejections.push(await api.call(e));
 await db.exec(`set check_function_bodies=off;create or replace function private.dashboard_admin_live_scope()returns jsonb language sql stable as $$select '{}'::jsonb$$;create or replace function private.dashboard_scope_allows(jsonb,text,text)returns boolean language sql stable as $$select coalesce(current_setting('test.allowed',true),'yes')='yes'and $2 in('IN','印度')and $3='WG-SYNTHETIC'$$;`);
 for(const n of ['dashboard_admin_live_blocking_core','dashboard_admin_live_blocking_details_cleaned','dashboard_admin_live_blocking_members','withdraw_reason_wg_atomic','dashboard_admin_live_withdraw_reasons'])await db.exec(read('sql/'+n+'.sql'));
 const call=async extra=>(await db.query('select private.dashboard_admin_live_withdraw_reasons($1)v',[{...q,...extra}])).rows[0].v;
 return {...api,db,originalCall:api.call,call,originalMeta,beforeRejections};}
test('WG parent routes atomic rules while preserving original unique manual/source totals and selected measurements',async()=>{const {db,call,seed,manual,checksum}=await wg(true);try{for(const [i,n,status]of [[1,`${A};${B}`,4],[2,`${A};${C}`,7],[3,B,2],[4,`${A};${A};${B}`,4]])await seed('ATOM-'+i,manual(n,{rejection_reason:'EXACT REJECTION'}),status);await seed('AUTO',manual(A,{operator_class:'auto',operator_name:'system'}));await seed('UNKNOWN',manual(A,{operator_class:'unknown',operator_name:null}));await seed('EMPTY',manual(null,{note_state:'empty'}),7);await seed('MISSING',manual(null,{note_state:undefined,front_note_state:undefined,back_note_state:undefined}),7);const before=await checksum();const d=await call();assert.equal(d.reasonGrouping,'atomic_rules_v1');assert.equal(d.noteCount,6);assert.equal(d.summary.operatorCounts.manual,6);assert.equal(d.summary.selectedCount,6);assert.equal(d.categories[0].count,6);assert.equal(d.summary.ruleMembership.hitCount,9);assert.equal(d.coverage.collected,8);const a=d.rows.find(r=>r.reason==='总打码倍数小于配置倍数');assert.equal(a.count,3);const orders=await call({kind:'blockingOrders',reasonKey:a.reasonKey});assert.equal(orders.total,3);const variants=await call({kind:'blockingVariants',reasonKey:a.reasonKey});assert.equal(variants.rows.reduce((n,r)=>n+r.count,0),3);assert.equal(variants.rows.find(r=>r.sourceReason===`${A};${A};${B}`).count,1);const filtered=await call({kind:'blockingOrders',reasonKey:a.reasonKey,query:'ATOM-4'});assert.equal(filtered.total,1);assert.equal(filtered.rows[0].orderNumber,'ATOM-4');assert.equal(filtered.summary.ruleMembership.hitCount,9);assert.equal(filtered.noteCount,6);assert.equal(orders.categories[0].count,3);assert.equal(orders.summary.selectedCount,3);assert.equal(orders.noteCount,6);assert(orders.rows.every(r=>r.blockingActualValue==='1.3720'&&r.blockingActualField==='总打码倍数'&&r.blockingThreshold==='4'));assert.deepEqual(orders.rows.map(r=>r.statusCode).sort(),[4,4,7]);assert(orders.rows.every(r=>r.amount===100&&r.currency==='INR'&&r.completedAt===null));assert.equal((await call({kind:'rejection'})).rows.find(r=>r.reason==='EXACT REJECTION').count,1);assert.equal(await checksum(),before);assert.equal(d.coverage.complete,true);for(const kind of ['blockingOrders','blockingVariants'])await assert.rejects(call({kind}),e=>e.code==='22023');await db.exec("select set_config('test.allowed','no',false)");await assert.rejects(call(),e=>e.code==='42501');}finally{await db.close();}});
test('all original WG non-blocking branches and original reader metadata stay byte-identical',async()=>{const {db,call,originalCall,originalMeta,beforeRejections,checksum}=await wg();try{const before=await checksum();for(let i=0;i<unaffected.length;i++)assert.deepEqual(await call(unaffected[i]),beforeRejections[i],JSON.stringify(unaffected[i]));assert.deepEqual((await db.query("select to_jsonb(p)v from pg_proc p where oid='private.dashboard_admin_wg_withdraw_reasons(jsonb,jsonb)'::regprocedure")).rows[0].v,originalMeta);const old=await originalCall(),next=await call();for(const key of ['noteCount','coverage','updatedAt','timeBasis','operatorBasis'])assert.deepEqual(next[key],old[key],key);for(const key of ['totalRejected','missingReason','withOperator','operators','operatorCounts','blockingCounts','selectedCount'])assert.deepEqual(next.summary[key],old.summary[key],key);assert.equal(next.categories[0].count,old.categories[0].count);const hidden=next.rows.find(x=>x.blockingNoteState==='withheld');assert.equal(hidden.sourceReason,null);assert.equal(hidden.sourceVariantCount,null);const literal=next.rows.find(x=>x.reason==='拦截说明已隐藏'&&x.blockingNoteState==='present');assert(literal);assert.notEqual(hidden.reasonKey,literal.reasonKey);assert.equal(await checksum(),before);}finally{await db.close();}});
